#!/usr/bin/env bash
# VERIFY-ONLY check of the committed Gradle wrapper. It never downloads, replaces or edits anything.
# Any mismatch fails the build, so a wrong or tampered wrapper can never be used silently.
#
# Usage: tools/verify_gradle_wrapper.sh <path-to-gradle-project>
#
# Expected values for Gradle 8.10.2
#   gradle-wrapper.jar : published by Gradle (https://gradle.org/release-checksums/)
#   gradle-8.10.2-bin.zip : published by Gradle; pinned in gradle-wrapper.properties
#   gradlew, gradlew.bat : not published by Gradle; these are the files generated by the
#                          checksum-verified 8.10.2 distribution (`gradle wrapper`), committed together
#                          with the jar. The jar and the scripts must always be replaced as a pair.
set -euo pipefail

PROJECT_DIR="${1:?usage: verify_gradle_wrapper.sh <gradle-project-dir>}"

EXPECTED_JAR_SHA256="2db75c40782f5e8ba1fc278a5574bab070adccb2d21ca5a6e5ed840888448046"
EXPECTED_GRADLEW_SHA256="a3648413b47ef77af21d5ebc36c687c7d103aaef3e17f33de7d4f080a6f300a3"
EXPECTED_GRADLEW_BAT_SHA256="57931b17dd228e5c24dac90e815d0bf82477e831a4618dfab4136f5446b42a9f"
EXPECTED_DIST_SHA256="31c55713e40233a8303827ceb42ca48a47267a0ad4bab9177123121e71524c26"

JAR="$PROJECT_DIR/gradle/wrapper/gradle-wrapper.jar"
PROPS="$PROJECT_DIR/gradle/wrapper/gradle-wrapper.properties"
GRADLEW="$PROJECT_DIR/gradlew"
GRADLEW_BAT="$PROJECT_DIR/gradlew.bat"

sha256() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1; fi
}

fail=0
check() { # label file expected
  [ -f "$2" ] || { echo "FAIL  $1: $2 not found"; fail=1; return; }
  local actual; actual="$(sha256 "$2")"
  if [ "$actual" = "$3" ]; then echo "OK    $1 SHA-256 $actual"
  else echo "FAIL  $1 SHA-256 mismatch"; echo "        expected $3"; echo "        actual   $actual"; fail=1; fi
}

check "gradle-wrapper.jar" "$JAR" "$EXPECTED_JAR_SHA256"
check "gradlew            " "$GRADLEW" "$EXPECTED_GRADLEW_SHA256"
check "gradlew.bat        " "$GRADLEW_BAT" "$EXPECTED_GRADLEW_BAT_SHA256"

if [ -f "$PROPS" ]; then
  if grep -q '^distributionUrl=.*gradle-8\.10\.2-bin\.zip$' "$PROPS"; then echo "OK    distributionUrl points at gradle-8.10.2-bin.zip"
  else echo "FAIL  distributionUrl is not gradle-8.10.2-bin.zip"; fail=1; fi
  if grep -qx "distributionSha256Sum=$EXPECTED_DIST_SHA256" "$PROPS"; then echo "OK    distributionSha256Sum pinned to $EXPECTED_DIST_SHA256"
  else echo "FAIL  distributionSha256Sum missing or not $EXPECTED_DIST_SHA256"; fail=1; fi
else
  echo "FAIL  $PROPS not found"; fail=1
fi

# Pair consistency: a gradlew that starts the wrapper with 'java -jar' needs Main-Class in the jar.
# (The genuine 8.10.2 jar has none and is started with -classpath ... GradleWrapperMain.)
if [ -f "$GRADLEW" ] && [ -f "$JAR" ]; then
  has_main_class=no
  if unzip -p "$JAR" META-INF/MANIFEST.MF 2>/dev/null | tr -d '\r' | grep -q '^Main-Class:'; then has_main_class=yes; fi
  if grep -q -- '-jar "\$APP_HOME/gradle/wrapper/gradle-wrapper.jar"' "$GRADLEW"; then style=jar; else style=classpath; fi
  echo "INFO  gradlew starts the wrapper with: $style; jar manifest has Main-Class: $has_main_class"
  if [ "$style" = "jar" ] && [ "$has_main_class" = "no" ]; then
    echo "FAIL  gradlew uses 'java -jar' but the jar has no Main-Class: this pair gives 'no main manifest attribute'"; fail=1
  fi
fi

if [ "$fail" -ne 0 ]; then
  echo "Gradle wrapper verification FAILED. Nothing was changed. Fix the committed wrapper files; do not bypass this check."
  exit 1
fi
echo "Gradle wrapper verification passed."
